1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	  .tape-bar {
57	    display: flex;
58	    justify-content: space-between;
59	    align-items: center;
60	    color: #adb5bd;
61	    font-size: 14px;
62	  }
63	  .tape-bar button {
64	    font-size: 14px;
65	    height: 28px;
66	    padding: 0 12px;
67	    background: #3a3f45;
68	  }
69	  .tape {
70	    max-height: 132px;
71	    overflow-y: auto;
72	    margin-top: 8px;
73	  }
74	  .tape-row {
75	    display: flex;
76	    justify-content: space-between;
77	    gap: 12px;
78	    padding: 4px 8px;
79	    color: #adb5bd;
80	    font-size: 15px;
81	  }
82	  .tape-expr { overflow-wrap: anywhere; }
83	  .tape-result { color: #fff; white-space: nowrap; }
84	  .tape-result::before { content: "= "; color: #adb5bd; }
85	  .mem {
86	    color: #f59f00;
87	    font-size: 14px;
88	    font-weight: 600;
89	    padding: 8px 8px 0;
90	  }
91	  .mem[data-active="false"] { opacity: 0.2; }
92	</style>
93	</head>
94	<body>
95	<div class="calc">
96	  <!-- [REQ-007] Running tape of past calculations, newest first. -->
97	  <div class="tape-bar">
98	    <span>History</span>
99	    <button data-testid="tape-clear">Clear</button>
100	  </div>
101	  <div class="tape" data-testid="calc-tape"></div>
102	  <!-- [REQ-009] Lit while memory holds a non-zero value. -->
103	  <div class="mem" data-testid="mem-indicator" data-active="false">M</div>
104	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
105	  <div class="keys">
106	    <!-- [REQ-009] Memory keys. -->
107	    <button class="clear" data-testid="key-mc">MC</button>
108	    <button class="clear" data-testid="key-mr">MR</button>
109	    <button class="clear wide" data-testid="key-mplus">M+</button>
110	
111	    <button class="clear wide" data-testid="key-lparen">(</button>
112	    <button class="clear wide" data-testid="key-rparen">)</button>
113	
114	    <!-- [REQ-006] % key removed; AC spans its place. -->
115	    <button class="clear wide" data-testid="key-clear">AC</button>
116	    <button class="clear" data-testid="key-sign">±</button>
117	    <button class="op" data-testid="key-div" data-op="/">÷</button>
118	
119	    <button data-testid="key-7">7</button>
120	    <button data-testid="key-8">8</button>
121	    <button data-testid="key-9">9</button>
122	    <button class="op" data-testid="key-mul" data-op="*">×</button>
123	
124	    <button data-testid="key-4">4</button>
125	    <button data-testid="key-5">5</button>
126	    <button data-testid="key-6">6</button>
127	    <button class="op" data-testid="key-sub" data-op="-">−</button>
128	
129	    <button data-testid="key-1">1</button>
130	    <button data-testid="key-2">2</button>
131	    <button data-testid="key-3">3</button>
132	    <button class="op" data-testid="key-add" data-op="+">+</button>
133	
134	    <button class="wide" data-testid="key-0">0</button>
135	    <button data-testid="key-dot">.</button>
136	    <button class="op" data-testid="key-equals">=</button>
137	  </div>
138	</div>
139	<script>
140	  var display = document.querySelector('[data-testid="calc-display"]');
141	  var tapeEl = document.querySelector('[data-testid="calc-tape"]');
142	  var memIndicator = document.querySelector('[data-testid="mem-indicator"]');
143	  var OP_SYMBOL = { '+': '+', '-': '−', '*': '×', '/': '÷' };
144	
145	  var state = {
146	    entry: '0',       // text of the number being shown/typed
147	    stored: null,     // left operand
148	    op: null,         // pending operator
149	    fresh: true,      // next digit starts a new entry
150	    typed: false,     // entry was typed by the user (shown as typed, not formatted)
151	    error: false,
152	    groups: [],       // [REQ-005] saved {stored, op, tokens} of each open "(", innermost last
153	    tokens: [],       // [REQ-007] expression text so far, not counting the current operand
154	    operandText: null, // [REQ-007] text of the current operand when it is a closed group
155	    memory: 0         // [REQ-009] exact, never rounded; AC leaves it alone
156	  };
157	
158	  // [REQ-003] Presentation only: at most 10 significant digits, no trailing
159	  // zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
160	  function formatNumber(v) {
161	    var r = Number(v.toPrecision(10));
162	    if (r === 0) return '0';
163	    var abs = Math.abs(r);
164	    if (abs >= 1e10 || abs < 1e-9) {
165	      return r.toExponential(9).replace(/\.?0+e/, 'e');
166	    }
167	    var e = Math.floor(Math.log10(abs));
168	    var s = r.toFixed(Math.max(0, 10 - e));
169	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
170	    return s;
171	  }
172	
173	  // [REQ-001]
174	  function compute(a, op, b) {
175	    switch (op) {
176	      case '+': return a + b;
177	      case '-': return a - b;
178	      case '*': return a * b;
179	      case '/': return a / b;
180	    }
181	    return b;
182	  }
183	
184	  // [REQ-001]
185	  // [REQ-003] Rounding happens here only; data-value keeps the exact value.
186	  function render() {
187	    var value = Number(state.entry);
188	    display.textContent = state.error ? 'Error' : (state.typed ? state.entry : formatNumber(value));
189	    display.setAttribute('data-value', state.error ? 'NaN' : String(value));
190	    display.setAttribute('data-error', state.error ? 'true' : 'false');
191	    memIndicator.setAttribute('data-active', state.memory !== 0 ? 'true' : 'false');
192	    document.querySelectorAll('button[data-op]').forEach(function (b) {
193	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
194	    });
195	  }
196	
197	  // [REQ-001]
198	  // [REQ-003] Division by zero (non-finite result) enters the error state.
199	  // String(value) is exact: Number(String(v)) === v.
200	  function setResult(value) {
201	    if (!isFinite(value)) {
202	      state.error = true;
203	      state.entry = '0';
204	      state.stored = null;
205	      state.op = null;
206	      state.groups = [];
207	      state.tokens = [];
208	      state.operandText = null;
209	    } else {
210	      state.entry = String(value);
211	    }
212	    state.typed = false;
213	    state.fresh = true;
214	  }
215	
216	  // [REQ-001]
217	  // [REQ-003] Ignored in the error state; only clear leaves it.
218	  // [REQ-004] A value set by ± is finished: the next digit starts a new entry.
219	  function inputDigit(d) {
220	    if (state.error) return;
221	    state.operandText = null;
222	    if (state.fresh || !state.typed) {
223	      state.entry = d;
224	      state.fresh = false;
225	    } else if (state.entry === '0' || state.entry === '-0') {
226	      state.entry = state.entry.slice(0, -1) + d;
227	    } else {
228	      state.entry += d;
229	    }
230	    state.typed = true;
231	  }
232	
233	  // [REQ-001]
234	  // [REQ-003] Ignored in the error state.
235	  function inputDot() {
236	    if (state.error) return;
237	    state.operandText = null;
238	    if (state.fresh || !state.typed) {
239	      state.entry = '0.';
240	      state.fresh = false;
241	    } else if (state.entry.indexOf('.') === -1) {
242	      state.entry += '.';
243	    }
244	    state.typed = true;
245	  }
246	
247	  // [REQ-004] ± flips the current entry. While typing it flips the text, so
248	  // typing continues. Otherwise the flipped value becomes the current operand.
249	  function toggleSign() {
250	    if (state.error) return;
251	    if (state.typed && !state.fresh) {
252	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
253	    } else {
254	      var text = state.operandText;
255	      setOperand(-Number(state.entry));
256	      // [REQ-007] A flipped group reads as -( … ) on the tape.
257	      if (text !== null) state.operandText = text.charAt(0) === '-' ? text.slice(1) : '-' + text;
258	    }
259	  }
260	
261	  // [REQ-004] A finished value that counts as the right operand if an operator
262	  // is waiting (so 2 × ( 3 + 4 ) = is 14), and is replaced by the next digit.
263	  function setOperand(value) {
264	    state.entry = String(value);
265	    state.typed = false;
266	    state.fresh = false;
267	  }
268	
269	  // [REQ-001]
270	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
271	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
272	  // [REQ-007] An operator pressed straight after another replaces it on the tape.
273	  function inputOperator(op) {
274	    if (state.error) return;
275	    if (state.op !== null && state.fresh) {
276	      state.tokens[state.tokens.length - 1] = OP_SYMBOL[op];
277	    } else {
278	      state.tokens.push(operandText(), OP_SYMBOL[op]);
279	    }
280	    state.operandText = null;
281	    if (state.op !== null && !state.fresh) {
282	      setResult(compute(state.stored, state.op, Number(state.entry)));
283	      if (state.error) return;
284	    }
285	    state.stored = Number(state.entry);
286	    state.op = op;
287	    state.fresh = true;
288	  }
289	
290	  // [REQ-005] "(" saves the waiting operation and starts an empty group.
291	  // Whatever the group evaluates to replaces the current entry.
292	  function openGroup() {
293	    if (state.error) return;
294	    state.groups.push({ stored: state.stored, op: state.op, tokens: state.tokens });
295	    state.tokens = [];
296	    state.operandText = null;
297	    state.stored = null;
298	    state.op = null;
299	    state.entry = '0';
300	    state.fresh = true;
301	    state.typed = false;
302	  }
303	
304	  // [REQ-005] ")" finishes the innermost group, restores the operation that
305	  // was waiting outside it, and uses the group's value as its right operand.
306	  // Ignored when no group is open.
307	  function closeGroup() {
308	    if (state.error || state.groups.length === 0) return;
309	    var value = state.op === null ? Number(state.entry)
310	      : compute(state.stored, state.op, Number(state.entry));
311	    if (!isFinite(value)) { setResult(value); return; }
312	    var outer = state.groups.pop();
313	    var text = '( ' + state.tokens.concat(operandText()).join(' ') + ' )';
314	    state.stored = outer.stored;
315	    state.op = outer.op;
316	    state.tokens = outer.tokens;
317	    setOperand(value);
318	    state.operandText = text;
319	  }
320	
321	  // [REQ-001]
322	  // [REQ-005] Open groups are closed first, so 2 × ( 3 + 4 = is 14.
323	  // [REQ-007] Each completed calculation adds a tape row. A lone number or an
324	  // error adds nothing.
325	  function equals() {
326	    if (state.error) return;
327	    var grouped = state.groups.length > 0 || state.operandText !== null;
328	    while (state.groups.length > 0 && !state.error) closeGroup();
329	    if (state.error || (state.op === null && !grouped)) return;
330	    var expr = state.tokens.concat(operandText()).join(' ');
331	    var result = state.op === null ? Number(state.entry)
332	      : compute(state.stored, state.op, Number(state.entry));
333	    state.stored = null;
334	    state.op = null;
335	    state.tokens = [];
336	    state.operandText = null;
337	    setResult(result);
338	    if (!state.error) addTapeRow(expr, result);
339	  }
340	
341	  // [REQ-007] Text of the current operand as it appears on the tape.
342	  function operandText() {
343	    if (state.operandText !== null) return state.operandText;
344	    if (state.typed) return state.entry.replace(/\.$/, '');
345	    return formatNumber(Number(state.entry));
346	  }
347	
348	  // [REQ-007] Newest row first. data-value holds the exact result.
349	  function addTapeRow(expr, value) {
350	    var row = document.createElement('div');
351	    row.className = 'tape-row';
352	    row.setAttribute('data-testid', 'tape-row');
353	    var exprEl = document.createElement('span');
354	    exprEl.className = 'tape-expr';
355	    exprEl.setAttribute('data-testid', 'tape-expr');
356	    exprEl.textContent = expr;
357	    var resultEl = document.createElement('span');
358	    resultEl.className = 'tape-result';
359	    resultEl.setAttribute('data-testid', 'tape-result');
360	    resultEl.setAttribute('data-value', String(value));
361	    resultEl.textContent = formatNumber(value);
362	    row.appendChild(exprEl);
363	    row.appendChild(resultEl);
364	    tapeEl.insertBefore(row, tapeEl.firstChild);
365	  }
366	
367	  // [REQ-009] M+ adds the exact displayed value, not its rounded text.
368	  // A typed entry is finished, so the next digit starts a new one. A sum that
369	  // is not finite enters the error state and leaves memory unchanged.
370	  function memoryAdd() {
371	    if (state.error) return;
372	    var sum = state.memory + Number(state.entry);
373	    if (!isFinite(sum)) { setResult(sum); return; }
374	    state.memory = sum;
375	    if (state.typed && !state.fresh) setOperand(Number(state.entry));
376	  }
377	
378	  // [REQ-009] MR works like a finished operand: it fills the right side of a
379	  // waiting operation and is replaced by the next digit.
380	  function memoryRecall() {
381	    if (state.error) return;
382	    state.operandText = null;
383	    setOperand(state.memory);
384	  }
385	
386	  // [REQ-009]
387	  function memoryClear() {
388	    if (state.error) return;
389	    state.memory = 0;
390	  }
391	
392	  // [REQ-001]
393	  function clearAll() {
394	    state.entry = '0';
395	    state.stored = null;
396	    state.op = null;
397	    state.fresh = true;
398	    state.typed = false;
399	    state.error = false;
400	    state.groups = [];
401	    state.tokens = [];
402	    state.operandText = null;
403	  }
404	
405	  document.querySelector('.keys').addEventListener('click', function (e) {
406	    var btn = e.target.closest('button');
407	    if (!btn) return;
408	    var id = btn.getAttribute('data-testid');
409	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
410	    else if (id === 'key-dot') inputDot();
411	    else if (id === 'key-sign') toggleSign();
412	    else if (id === 'key-lparen') openGroup();
413	    else if (id === 'key-rparen') closeGroup();
414	    else if (id === 'key-equals') equals();
415	    else if (id === 'key-clear') clearAll();
416	    else if (id === 'key-mplus') memoryAdd();
417	    else if (id === 'key-mr') memoryRecall();
418	    else if (id === 'key-mc') memoryClear();
419	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
420	    render();
421	  });
422	
423	  // [REQ-007] Empties the tape only; the display is left as it is.
424	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
425	    tapeEl.textContent = '';
426	  });
427	
428	  render();
429	</script>
430	</body>
431	</html>
