var MAP={'+':'key-add','-':'key-sub','*':'key-mul','/':'key-div','=':'key-equals','.':'key-dot','(':'key-lparen',')':'key-rparen','±':'key-sign','C':'key-clear','M+':'key-mplus','MR':'key-mr','MC':'key-mc','√':'key-sqrt','²':'key-square','r':'key-recip','S':'key-sci'};
function press(seq){seq.split(' ').forEach(function(t){var id=MAP[t]||('key-'+t); if(/^\d+$/.test(t)&&t.length>1){t.split('').forEach(function(d){q('key-'+d).click();});return;} q(id).click();});}
function keys(list){list.forEach(function(k){document.dispatchEvent(new KeyboardEvent('keydown',{key:k,bubbles:true,cancelable:true}));});}
function disp(){return q('calc-display').textContent;}
function check(name,got,want){out.push((got===want?'PASS ':'FAIL ')+name+' got='+JSON.stringify(got)+' want='+JSON.stringify(want));}
function reset(){press('C');q('tape-clear').click();press('MC');}
function t(name,seq,want){reset();press(seq);check(name,disp(),want);}
t('add','2 + 3 =','5');
t('no precedence','2 + 3 * 4 =','20');
t('op replace','5 + * 2 =','10');
t('decimal','0.1 + 0.2 =','0.3'.replace('0.3','0.3'));
t('div zero','1 / 0 =','Error');
t('error sticky','1 / 0 = 5','Error');
t('round','2 / 3 =','0.6666666667');
t('big','99999 * 99999 * 99999 =', disp()); // placeholder
reset();press('99999 * 99999 * 99999 =');check('big exp',/e/.test(disp()),true);
t('sign','5 ± + 2 =','-3');
t('sign typing','5 ± 3','-53');
t('group','2 * ( 3 + 4 ) =','14');
t('group autoclose','2 * ( 3 + 4 =','14');
reset();press('2 + 3 =');check('tape row',q('calc-tape').children.length+':'+document.querySelector('[data-testid="tape-expr"]').textContent,'1:2 + 3');
reset();press('5 =');check('lone no row',q('calc-tape').children.length,0);
reset();press('1 / 0 =');check('error no row',q('calc-tape').children.length,0);
reset();press('2 / 3 = M+ C MR * 3 =');check('memory exact',disp(),'2');
reset();press('4 M+');check('mem indicator',q('mem-indicator').getAttribute('data-active'),'true');
// keyboard
reset();keys(['1','2','.','5','+','2','Enter']);check('kbd enter',disp(),'14.5');
reset();keys(['8','/','2','=']);check('kbd =',disp(),'4');
reset();keys(['9','-','4','*','2','Enter']);check('kbd ops',disp(),'10');
reset();keys(['9','Escape']);check('kbd escape',disp(),'0');
// sci
reset();check('panel hidden',document.getElementById('sci-panel').hidden,true);
press('S');check('panel open',document.getElementById('sci-panel').hidden,false);
press('9 √');check('sqrt',disp(),'3');
press('C 4 ²');check('square',disp(),'16');
press('C 4 r');check('recip',disp(),'0.25');
press('C 2 + 9 √ =');check('sqrt operand',disp(),'5');
check('sqrt tape',document.querySelector('[data-testid="tape-expr"]').textContent,'2 + √9');
press('C 9 √ 5');check('digit after fn',disp(),'5');
press('C 4 ± √');check('sqrt neg',disp(),'Error');
press('C 0 r');check('recip zero',disp(),'Error');
press('S');check('panel close',document.getElementById('sci-panel').hidden,true);
document.body.setAttribute('data-results',out.join('\n'));
})();
</script>
